let activeFuel='Tutte';const $=id=>document.getElementById(id);$('allCount').textContent=data.length;$('brandCount').textContent=new Set(data.map(x=>x.brand)).size;for(const b of [...new Set(data.map(x=>x.brand))].sort((a,b)=>a.localeCompare(b))){let e=document.createElement('option');e.value=b;e.textContent=b;$('brand').append(e)};
function matchesPrice(x,v){const uf=v('usedFrom'),ut=v('usedTo'),nf=v('newFrom'),nt=v('newTo');const usedActive=uf!==''||ut!=='';const newActive=nf!==''||nt!=='';const usedOk=x.market.usedFrom!==null&&(!uf||x.market.usedFrom>=Number(uf))&&(!ut||x.market.usedFrom<=Number(ut));const newOk=!!x.market.new&&(!nf||x.market.new.price>=Number(nf))&&(!nt||x.market.new.price<=Number(nt));const mode=v('availability');if(mode==='new')return !newActive||newOk;if(mode==='used')return !usedActive||usedOk;return (!usedActive&&!newActive)||(usedActive&&usedOk)||(newActive&&newOk)}
function render(){const v=id=>$(id).value;const q=v('q').toLocaleLowerCase('it').trim();let a=data.filter(x=>matchesReviewFilters(x,v)&&(!v('fidelityMin')||videoFidelity(x).score>=Number(v('fidelityMin')))&&(activeFuel==='Tutte'||x.fuel===activeFuel)&&(!q||[x.brand,x.model,x.engine,x.note].join(' ').toLocaleLowerCase('it').includes(q))&&(!v('brand')||x.brand===v('brand'))&&(!v('cc')||(v('cc')==='small'&&x.cc<=1.6)||(v('cc')==='medium'&&x.cc>1.6&&x.cc<=2)||(v('cc')==='large'&&x.cc>2))&&(!v('asp')||x.asp===v('asp'))&&(!v('cyl')||x.cyl===Number(v('cyl')))&&(!v('timing')||x.timing===v('timing'))&&(!v('trans')||x.gearTypes.includes(v('trans')))&&(!v('usage')||x.usage===v('usage'))&&(!v('status')||x.fit===v('status'))&&(!v('inj')||x.inj===v('inj'))&&(!v('hybrid')||x.hybrid===v('hybrid'))&&(!v('power')||(v('power')==='below'?x.specificPower!==null&&x.specificPower<85:x.specificPower===null))&&(!v('availability')||v('availability')==='used'||!!x.market.new)&&(!v('yearFrom')||(x.market.yearTo!==null&&x.market.yearTo>=Number(v('yearFrom'))))&&(!v('yearTo')||(x.market.yearFrom!==null&&x.market.yearFrom<=Number(v('yearTo'))))&&matchesPrice(x,v));const s=v('sort');a.sort((x,y)=>s==='fidelity'?videoFidelity(y).score-videoFidelity(x).score||x.brand.localeCompare(y.brand):s==='cc'?x.cc-y.cc:s==='fuel'?x.fuel.localeCompare(y.fuel)||x.brand.localeCompare(y.brand):s==='usedPrice'?(x.market.usedFrom??Infinity)-(y.market.usedFrom??Infinity)||x.brand.localeCompare(y.brand):x.brand.localeCompare(y.brand)||x.model.localeCompare(y.model));$('shown').textContent=a.length; $('resultContext').textContent=resultContext(a,v);$('empty').hidden=!!a.length;$('cards').innerHTML=a.map(x=>`<article class="card">${photoMeta[photoKeys[x.id]]?`<figure class="carphoto"><img src="${photoMeta[photoKeys[x.id]].src}" alt="Foto esemplificativa: ${safe(x.brand)} ${safe(usedNames[x.id])}" loading="lazy" decoding="async"></figure><div class="photocredit">Foto esemplificativa · <a href="${photoMeta[photoKeys[x.id]].file}" target="_blank" rel="noopener noreferrer">${safe(photoMeta[photoKeys[x.id]].author||'Wikimedia Commons')}</a> · <a href="${photoMeta[photoKeys[x.id]].licenseUrl}" target="_blank" rel="noopener noreferrer">${safe(photoMeta[photoKeys[x.id]].license||'licenza')}</a> · ridimensionata e convertita in WebP</div>`:`<div class="modelplaceholder"><span>${safe(x.brand)}</span><strong>${safe(x.model)}</strong><small>IMMAGINE EDITORIALE · DETTAGLIO MECCANICO</small></div>`}<div class="small">${x.brand} · ${x.fuel}</div><h3>${x.model}</h3><p class="engine">${x.engine}</p><span class="badge ${x.hybrid==='Honda'?'honda':x.fit==='Coerente per architettura'?'':'caution'}">${x.fit}</span><div class="tags" style="margin-top:13px"><span class="tag">${x.cc.toFixed(1)} L</span><span class="tag">${x.cyl} cilindri</span><span class="tag">${x.asp}</span><span class="tag">${x.timing}</span><span class="tag">${x.trans}</span><span class="tag">Iniezione: ${x.inj}</span>${x.hybrid?`<span class="tag">${x.hybrid}</span>`:''}${x.specificPower!==null?`<span class="tag">≈${x.specificPower.toFixed(1)} CV/L termico</span>`:''}</div>${fidelityCard(x)}${reviewedEngineSheet(x)}<div class="marketbox"><div><b>Anni indicativi</b><strong>${x.market.yearFrom!==null&&x.market.yearTo!==null?`${x.market.yearFrom}–${x.market.yearTo}`:'Da verificare'}</strong></div><div><b>Usato · ${safe(usedNames[x.id])}</b><strong>${x.market.usedFrom!==null?`Da ${euro(x.market.usedFrom)}`:"Prezzo da verificare"}</strong>${x.market.usedTo!==null?`<small>Fascia del modello fino a ${euro(x.market.usedTo)}</small>`:""}${x.market.usedSource?`<a href="${x.market.usedSource}" target="_blank" rel="noopener noreferrer">Fonte indicativa ↗</a>`:""}</div><div><b>Nuovo</b>${x.market.new?`<strong>Da ${euro(x.market.new.price)}</strong><small>${safe(x.market.new.model)} · listino</small>`:'<small>Versione esatta non verificata in gamma</small>'}</div></div><div class="actions">${x.market.new?`<a href="${x.market.new.link}" target="_blank" rel="noopener noreferrer" aria-label="${safe(x.market.new.model)} nuova sul sito ufficiale">Nuova verificata ↗</a>`:''}<a class="secondary" href="https://www.autoscout24.it/lst/${brandLinks[x.brand][1]}/${usedSlugs[x.id]}" target="_blank" rel="noopener noreferrer" aria-label="Cerca ${safe(x.brand)} ${safe(usedNames[x.id])} usate in Italia">${safe(usedNames[x.id])} usate ↗</a></div><p class="availnote">Prezzo d’ingresso indicativo del modello, non un’offerta garantita per il motore esatto; le schede senza dato sono escluse dal filtro prezzo usato. Verifica anno, chilometri e codice P.5. Nuovo solo per versioni con motorizzazione riscontrata nella gamma italiana.</p></article>`).join('')}
for(const id of ['q','brand','cc','asp','cyl','timing','trans','usage','status','inj','hybrid','power','availability','yearFrom','yearTo','usedFrom','usedTo','newFrom','newTo','scope','timingLayout','pump','dpf','maturity','fidelityMin','sort'])$(id).addEventListener(['q','yearFrom','yearTo','usedFrom','usedTo','newFrom','newTo'].includes(id)?'input':'change',()=>{if(['usedFrom','usedTo'].includes(id)&&$('sort').value==='brand')$('sort').value='usedPrice';render()});document.querySelectorAll('[data-fuel]').forEach(b=>b.addEventListener('click',()=>{activeFuel=b.dataset.fuel;document.querySelectorAll('[data-fuel]').forEach(c=>c.classList.toggle('active',c===b));render()}));$('reset').onclick=()=>{for(const id of ['q','brand','cc','asp','cyl','timing','trans','usage','status','inj','hybrid','power','availability','yearFrom','yearTo','usedFrom','usedTo','newFrom','newTo','timingLayout','pump','dpf','maturity','fidelityMin'])$(id).value='';$('scope').value='candidates';$('sort').value='brand';activeFuel='Tutte';document.querySelectorAll('[data-fuel]').forEach(c=>c.classList.toggle('active',c.dataset.fuel==='Tutte'));render()};render();

// Scorciatoie per i tre profili descritti nella trascrizione.
document.querySelectorAll('[data-profile]').forEach(button=>button.addEventListener('click',()=>{
  $('reset').click();
  const profile=button.dataset.profile;
  activeFuel=profile==='petrol'?'Benzina':profile==='hybrid'?'Full hybrid':'Diesel';
  document.querySelectorAll('[data-fuel]').forEach(c=>c.classList.toggle('active',c.dataset.fuel===activeFuel));
  if(profile==='petrol'){$('asp').value='Aspirato';$('inj').value='MPI';}
  if(profile==='hybrid')$('scope').value='architecture';
  if(profile==='diesel')$('usage').value='Autostrada';
  render();$('cards').scrollIntoView({behavior:'smooth',block:'start'});
}));
$('status').addEventListener('change',()=>{if($('status').value==='Fuori profilo stretto')$('scope').value='all';render()});
$('annualKm').addEventListener('input',()=>{
  const km=Number($('annualKm').value);
  $('usageAdvice').textContent=!km?'Il tipo di percorso conta quanto i chilometri: il diesel richiede viaggi sufficientemente lunghi e regolari.':km<=20000?'Secondo il video: valuta benzina aspirato MPI/doppia iniezione o full hybrid per città e misto. I tragitti brevi rendono il diesel meno adatto.':km>=25000?'Secondo il video: il diesel si valuta se questi chilometri sono prevalentemente su strada veloce e il motore resta in temperatura. I chilometri da soli non bastano.':'Tra 20.000 e 25.000 km il video non stabilisce una scelta netta: confronta lunghezza dei tragitti, percorsi e costi reali.';
});
$('totalBudget').addEventListener('input',()=>{
  const total=Number($('totalBudget').value);
  $('applyBudget').disabled=total<=0;
  $('budgetAdvice').textContent=total>0?`Tetto orientativo per l’auto: ${euro(Math.floor(total*.85))}. Riserva del 15%: ${euro(total*.15)}.`:'Accantona il 15% per controlli e interventi iniziali, secondo la proposta del video.';
});
$('applyBudget').addEventListener('click',()=>{
  const total=Number($('totalBudget').value);if(total<=0)return;
  $('usedTo').value=Math.floor(total*.85);$('availability').value='used';$('sort').value='usedPrice';render();
  $('resultContext').scrollIntoView({behavior:'smooth',block:'center'});
});
